import { createReadStream, existsSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));

const MIME: Record<string, string> = {
	".html": "text/html; charset=utf-8",
	".js": "application/javascript; charset=utf-8",
	".css": "text/css; charset=utf-8",
	".json": "application/json; charset=utf-8",
	".svg": "image/svg+xml",
	".png": "image/png",
	".ico": "image/x-icon",
};

export interface HttpServerOptions {
	publicDir: string;
}

export function createHttpServer(options: HttpServerOptions): ReturnType<typeof createServer> {
	const publicRoot = normalize(options.publicDir);

	const server = createServer((req, res) => {
		const url = new URL(req.url ?? "/", "http://localhost");

		if (url.pathname === "/health") {
			res.writeHead(200, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ ok: true }));
			return;
		}

		let filePath = url.pathname === "/" ? "/index.html" : url.pathname;
		const resolved = normalize(join(publicRoot, filePath));
		if (!resolved.startsWith(publicRoot)) {
			res.writeHead(403);
			res.end("Forbidden");
			return;
		}

		if (!existsSync(resolved) || statSync(resolved).isDirectory()) {
			const indexFallback = join(publicRoot, "index.html");
			if (existsSync(indexFallback)) {
				filePath = "/index.html";
			} else {
				res.writeHead(404);
				res.end("Not found");
				return;
			}
		}

		const finalPath = filePath === "/index.html" && !existsSync(resolved) ? join(publicRoot, "index.html") : resolved;
		const ext = extname(finalPath);
		res.writeHead(200, { "Content-Type": MIME[ext] ?? "application/octet-stream" });
		createReadStream(finalPath).pipe(res);
	});

	return server;
}

export function defaultPublicDir(): string {
	return join(__dirname, "public");
}

{
	"name": "@earendil-works/pi-hub",
	"version": "0.75.3",
	"description": "LAN WebSocket hub for collaborative pi coding-agent sessions",
	"type": "module",
	"bin": {
		"pi-hub": "dist/cli.js"
	},
	"main": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		}
	},
	"files": [
		"dist",
		"README.md",
		"CHANGELOG.md"
	],
	"scripts": {
		"clean": "shx rm -rf dist",
		"build": "node scripts/build.mjs",
		"start": "node dist/cli.js",
		"init": "node dist/cli.js init",
		"test": "vitest --run",
		"prepublishOnly": "npm run clean && npm run build"
	},
	"dependencies": {
		"@earendil-works/pi-coding-agent": "^0.75.3",
		"ws": "8.18.3"
	},
	"devDependencies": {
		"@earendil-works/pi-ai": "^0.75.3",
		"@types/node": "22.19.19",
		"@types/ws": "8.18.1",
		"esbuild": "0.28.0",
		"shx": "0.4.0",
		"typescript": "5.9.3",
		"vitest": "3.2.4"
	},
	"keywords": [
		"pi",
		"agent",
		"websocket",
		"collaboration",
		"lan"
	],
	"author": "Mario Zechner",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/earendil-works/pi-mono.git",
		"directory": "packages/hub"
	},
	"engines": {
		"node": ">=22.19.0"
	}
}

import { chmodSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { cpSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";

function loadEsbuild() {
	const paths = [
		"esbuild",
		"../../../node_modules/esbuild",
		"../../../../node_modules/esbuild",
	];
	const require = createRequire(import.meta.url);
	for (const p of paths) {
		try {
			return require(p);
		} catch {
			// try next
		}
	}
	throw new Error("esbuild not found; run npm install from repo root");
}

const esbuild = loadEsbuild();

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dist = join(root, "dist");

await esbuild.build({
	entryPoints: [join(root, "src", "cli.ts"), join(root, "src", "index.ts")],
	bundle: true,
	platform: "node",
	format: "esm",
	outdir: dist,
	packages: "external",
});

await esbuild.build({
	entryPoints: [join(root, "test", "run-ws-smoke.mjs")],
	bundle: true,
	platform: "node",
	format: "esm",
	outfile: join(dist, "run-ws-smoke.js"),
	packages: "external",
});

chmodSync(join(dist, "cli.js"), 0o755);

mkdirSync(join(dist, "public"), { recursive: true });
const webDist = join(root, "..", "web", "dist");
cpSync(webDist, join(dist, "public"), { recursive: true });

console.log("Built pi-hub to", dist);

:root {
	--canvas: #000000;
	--surface: #0a0a0a;
	--surface-raised: #111111;
	--border: rgba(255, 255, 255, 0.08);
	--border-strong: rgba(255, 255, 255, 0.14);
	--text: #ffffff;
	--text-body: #a3a3a3;
	--muted: #737373;
	--accent: #ffffff;
	--accent-hover: #e5e5e5;
	--accent-ink: #000000;
	--accent-glow: rgba(255, 255, 255, 0.12);
	--user-bg: rgba(255, 255, 255, 0.06);
	--user-border: rgba(255, 255, 255, 0.14);
	--assistant-bg: #111111;
	--tool-bg: #0a0a0a;
	--error: #f87171;
	--error-bg: rgba(248, 113, 113, 0.1);
	--warning-bg: rgba(251, 191, 36, 0.1);
	--warning-text: #fbbf24;
	--plan-bg: rgba(255, 255, 255, 0.04);
	--progress: #d4d4d4;
	--font-display: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
	--font: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
	--mono: "IBM Plex Mono", ui-monospace, monospace;
	--radius-pill: 9999px;
	--radius-card: 12px;
	--radius-input: 12px;
	--ease-out: cubic-bezier(0.22, 1, 0.36, 1);
	--duration-fast: 150ms;
	--duration-normal: 280ms;
	--sidebar-width: 300px;
}

* {
	box-sizing: border-box;
}

html {
	height: 100%;
	color-scheme: dark;
}

body {
	margin: 0;
	font-family: var(--font);
	font-weight: 400;
	letter-spacing: -0.02em;
	background: var(--canvas);
	color: var(--text-body);
	height: 100vh;
	overflow: hidden;
	-webkit-font-smoothing: antialiased;
}

body::before {
	content: "";
	position: fixed;
	inset: 0;
	pointer-events: none;
	z-index: 0;
	background:
		radial-gradient(ellipse 70% 45% at 50% -15%, rgba(255, 255, 255, 0.07), transparent 55%),
		radial-gradient(ellipse 50% 35% at 100% 100%, rgba(255, 255, 255, 0.04), transparent 50%),
		radial-gradient(ellipse 40% 30% at 0% 85%, rgba(255, 255, 255, 0.03), transparent 45%);
}

#app {
	position: relative;
	z-index: 1;
	display: flex;
	flex-direction: column;
	height: 100vh;
	transition: opacity var(--duration-fast) ease;
}

#app.view-exit {
	opacity: 0;
}

#app.view-enter {
	animation: view-crossfade var(--duration-normal) var(--ease-out) both;
}

:focus-visible {
	outline: 2px solid rgba(255, 255, 255, 0.5);
	outline-offset: 2px;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible,
button:focus-visible {
	outline: 2px solid rgba(255, 255, 255, 0.45);
	outline-offset: 2px;
}

/* Shared controls */

.secondary-btn {
	padding: 0.45rem 0.9rem;
	background: transparent;
	color: var(--text-body);
	border: 1px solid var(--border-strong);
	border-radius: var(--radius-pill);
	cursor: pointer;
	font: inherit;
	font-size: 0.8125rem;
	letter-spacing: -0.01em;
	transition:
		border-color var(--duration-fast),
		color var(--duration-fast),
		background var(--duration-fast),
		transform var(--duration-fast) var(--ease-out);
}

.secondary-btn:hover {
	border-color: rgba(255, 255, 255, 0.28);
	color: var(--text);
	background: rgba(255, 255, 255, 0.04);
}

.secondary-btn:active {
	transform: scale(0.98);
}

input,
textarea,
select {
	background: var(--surface);
	color: var(--text);
	border: 1px solid var(--border);
	border-radius: var(--radius-input);
	font: inherit;
	letter-spacing: -0.01em;
	transition:
		border-color var(--duration-fast),
		box-shadow var(--duration-fast);
}

input:focus,
textarea:focus,
select:focus {
	outline: none;
	border-color: rgba(255, 255, 255, 0.35);
	box-shadow: 0 0 0 3px var(--accent-glow);
}

/* Connect */

.connect-shell {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	min-height: 100vh;
	padding: 2.5rem 1.25rem;
}

.connect-hero {
	text-align: center;
	margin-bottom: 2.5rem;
	animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.connect-hero .eyebrow {
	font-family: var(--mono);
	font-size: 0.7rem;
	letter-spacing: 0.14em;
	text-transform: uppercase;
	color: var(--muted);
	margin: 0 0 1rem;
}

.connect-hero h1 {
	margin: 0;
	font-family: var(--font-display);
	font-size: clamp(2.5rem, 8vw, 4rem);
	font-weight: 300;
	letter-spacing: -0.04em;
	color: var(--text);
	line-height: 1.05;
}

.connect-panel {
	width: 100%;
	max-width: 420px;
	display: flex;
	flex-direction: column;
	gap: 0.65rem;
	padding: 1.75rem;
	background: var(--surface-raised);
	border: 1px solid var(--border-strong);
	border-radius: var(--radius-card);
	animation: fade-up var(--duration-normal) var(--ease-out) 0.08s both;
}

.connect-panel .hint {
	margin: 0 0 0.25rem;
	font-size: 0.8125rem;
	line-height: 1.55;
	color: var(--muted);
	letter-spacing: -0.01em;
}

.connect-panel label {
	display: flex;
	flex-direction: column;
	gap: 0.35rem;
	animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.connect-panel label:nth-of-type(1) {
	animation-delay: 0.12s;
}
.connect-panel label:nth-of-type(2) {
	animation-delay: 0.16s;
}
.connect-panel label:nth-of-type(3) {
	animation-delay: 0.2s;
}
.connect-panel label:nth-of-type(4) {
	animation-delay: 0.24s;
}

.connect-panel label span {
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.12em;
	text-transform: uppercase;
	color: var(--muted);
}

.connect-panel input {
	padding: 0.65rem 0.85rem;
}

.connect-rooms {
	animation: fade-up var(--duration-normal) var(--ease-out) 0.28s both;
}

.connect-rooms select {
	width: 100%;
	margin: 0.35rem 0;
	padding: 0.55rem 0.75rem;
}

.connect-panel .btn-primary {
	margin-top: 0.5rem;
	padding: 0.75rem 1.35rem;
	background: var(--accent);
	color: var(--accent-ink);
	border: 1px solid transparent;
	border-radius: var(--radius-pill);
	cursor: pointer;
	font: inherit;
	font-weight: 500;
	letter-spacing: -0.02em;
	animation: fade-up var(--duration-normal) var(--ease-out) 0.32s both;
	transition:
		transform var(--duration-fast) var(--ease-out),
		background var(--duration-fast),
		opacity var(--duration-fast);
}

.connect-panel .btn-primary:hover {
	background: var(--accent-hover);
	transform: translateY(-1px);
}

.connect-panel .btn-primary:active {
	transform: translateY(0);
}

/* Room lobby */

.lobby-shell {
	display: flex;
	flex-direction: column;
	min-height: 100vh;
	max-width: 560px;
	margin: 0 auto;
	padding: 1.25rem 1.25rem 2rem;
	animation: fade-in var(--duration-normal) var(--ease-out) both;
}

.lobby-header {
	display: flex;
	align-items: center;
	gap: 0.75rem;
	padding: 0.5rem 0 1.25rem;
	border-bottom: 1px solid var(--border-strong);
	margin-bottom: 1rem;
}

.lobby-title {
	margin: 0;
	flex: 1;
	font-family: var(--font-display);
	font-size: 1.5rem;
	font-weight: 300;
	letter-spacing: -0.03em;
	color: var(--text);
}

.lobby-user {
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--muted);
}

.lobby-create-row {
	display: flex;
	gap: 0.5rem;
	margin-bottom: 1rem;
}

.lobby-create-row input {
	flex: 1;
	padding: 0.6rem 0.85rem;
}

.room-list {
	list-style: none;
	margin: 0;
	padding: 0;
	flex: 1;
	overflow-y: auto;
	display: flex;
	flex-direction: column;
	gap: 0.35rem;
}

.room-list-empty {
	padding: 1.5rem 0.5rem;
	color: var(--muted);
	font-size: 0.875rem;
	text-align: center;
}

.room-list li {
	display: flex;
	align-items: stretch;
	gap: 0.35rem;
	animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.room-row {
	flex: 1;
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 0.25rem;
	text-align: left;
	border: 1px solid var(--border);
	border-radius: var(--radius-card);
	background: var(--surface-raised);
	padding: 0.85rem 1rem;
	cursor: pointer;
	font: inherit;
	color: var(--text);
	transition:
		border-color var(--duration-fast),
		background var(--duration-fast),
		transform var(--duration-fast) var(--ease-out);
}

.room-row:hover {
	border-color: rgba(255, 255, 255, 0.22);
	background: rgba(255, 255, 255, 0.04);
	transform: translateY(-1px);
}

.room-row.active {
	border-left: 2px solid var(--accent);
	background: rgba(255, 255, 255, 0.06);
}

.room-row-title {
	font-size: 0.95rem;
	font-weight: 500;
	letter-spacing: -0.02em;
}

.room-card-meta {
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.06em;
	color: var(--muted);
}

.room-row-actions {
	display: flex;
	align-items: center;
	flex-shrink: 0;
}

.room-row-actions .secondary-btn {
	font-size: 0.75rem;
	padding: 0.4rem 0.65rem;
}

.header-rooms-btn {
	margin-right: 0.25rem;
	font-size: 0.75rem;
	padding: 0.4rem 0.75rem;
}

/* Chat layout */

.chat-layout {
	display: flex;
	flex: 1;
	min-height: 0;
	height: 100%;
	position: relative;
}

.sidebar-backdrop {
	display: none;
	position: fixed;
	inset: 0;
	z-index: 40;
	background: rgba(0, 0, 0, 0.55);
	backdrop-filter: blur(4px);
	opacity: 0;
	transition: opacity var(--duration-fast) ease;
	pointer-events: none;
}

.sidebar-backdrop.visible {
	opacity: 1;
	pointer-events: auto;
}

.sidebar {
	width: var(--sidebar-width);
	flex-shrink: 0;
	border-right: 1px solid var(--border-strong);
	background: var(--surface);
	overflow-y: auto;
	padding: 0.85rem;
	display: flex;
	flex-direction: column;
	gap: 0.35rem;
	transition: transform var(--duration-normal) var(--ease-out);
}

.sidebar-section {
	border: none;
	border-radius: 0;
	padding: 0.35rem 0;
	background: transparent;
	border-bottom: 1px solid var(--border);
	animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.sidebar-section:nth-child(1) {
	animation-delay: 0.04s;
}
.sidebar-section:nth-child(2) {
	animation-delay: 0.08s;
}
.sidebar-section:nth-child(3) {
	animation-delay: 0.12s;
}
.sidebar-section:nth-child(4) {
	animation-delay: 0.16s;
}

.sidebar-section summary {
	cursor: pointer;
	font-weight: 500;
	color: var(--text);
	padding: 0.45rem 0.25rem;
	border-radius: 6px;
	transition: background var(--duration-fast);
}

.sidebar-section summary:hover {
	background: rgba(255, 255, 255, 0.04);
}

.sidebar-section input,
.sidebar-section textarea,
.sidebar-section select {
	width: 100%;
	margin: 0.35rem 0;
	padding: 0.45rem 0.55rem;
	font-size: 0.8125rem;
}

.sidebar-section label {
	display: flex;
	align-items: center;
	gap: 0.4rem;
	font-size: 0.8125rem;
	color: var(--text-body);
	margin: 0.35rem 0;
}

.sidebar-row,
.room-actions,
.connect-rooms .room-actions {
	display: flex;
	gap: 0.35rem;
	flex-wrap: wrap;
	margin-top: 0.35rem;
}

.rooms-list {
	list-style: none;
	margin: 0.5rem 0;
	padding: 0;
}

.rooms-list li {
	margin: 0.15rem 0;
}

.room-link {
	width: 100%;
	text-align: left;
	border: none;
	background: transparent;
	padding: 0.45rem 0.55rem;
	border-radius: 6px;
	cursor: pointer;
	font: inherit;
	color: var(--text-body);
	border-left: 2px solid transparent;
	transition:
		background var(--duration-fast),
		color var(--duration-fast),
		border-color var(--duration-fast);
}

.room-link:hover {
	background: rgba(255, 255, 255, 0.04);
	color: var(--text);
}

.room-link.active {
	background: rgba(255, 255, 255, 0.06);
	color: var(--text);
	border-left-color: var(--accent);
}

.role-editor {
	width: 100%;
	font-family: var(--mono);
	font-size: 0.75rem;
	margin: 0.35rem 0;
	min-height: 8rem;
	padding: 0.55rem 0.65rem;
	line-height: 1.45;
}

.role-meta {
	font-size: 0.7rem;
	color: var(--muted);
	margin-bottom: 0.25rem;
	word-break: break-all;
}

.danger-btn {
	color: var(--error);
}

.danger-btn:hover {
	border-color: rgba(248, 113, 113, 0.35);
	color: var(--error);
}

.room-assigned-list {
	list-style: none;
	margin: 0.5rem 0;
	padding: 0;
}

.room-assigned-item {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.35rem;
	margin: 0.2rem 0;
	padding: 0.25rem 0;
}

.room-assigned-item span {
	font-size: 0.85rem;
	color: var(--text);
}

.chat-panel {
	display: flex;
	flex-direction: column;
	flex: 1;
	height: 100%;
	min-height: 0;
	min-width: 0;
	animation: fade-in var(--duration-normal) var(--ease-out) both;
}

.header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 1rem;
	padding: 0.85rem 1.25rem;
	border-bottom: 1px solid var(--border-strong);
	background: rgba(0, 0, 0, 0.72);
	backdrop-filter: blur(16px);
}

.sidebar-toggle {
	display: none;
	flex-shrink: 0;
	padding: 0.4rem 0.65rem;
	background: transparent;
	color: var(--text);
	border: 1px solid var(--border-strong);
	border-radius: var(--radius-pill);
	cursor: pointer;
	font: inherit;
	font-size: 0.75rem;
	letter-spacing: 0.04em;
	transition:
		border-color var(--duration-fast),
		background var(--duration-fast);
}

.sidebar-toggle:hover {
	background: rgba(255, 255, 255, 0.06);
	border-color: rgba(255, 255, 255, 0.22);
}

.header-brand {
	display: flex;
	align-items: center;
	gap: 0.65rem;
	min-width: 0;
}

.header-brand .logo {
	font-size: 0.95rem;
	font-weight: 500;
	letter-spacing: -0.03em;
	color: var(--text);
	white-space: nowrap;
}

.header-brand .room {
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--muted);
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.header .status-wrap {
	display: flex;
	align-items: center;
	gap: 0.45rem;
	flex-shrink: 0;
}

.status-dot {
	width: 6px;
	height: 6px;
	border-radius: 50%;
	background: var(--muted);
	flex-shrink: 0;
	transition: background var(--duration-normal);
}

.status-dot.live {
	background: var(--accent);
	box-shadow: 0 0 10px rgba(255, 255, 255, 0.35);
	animation: pulse-dot 2s ease-in-out infinite;
}

.status-dot.connecting {
	background: #525252;
	animation: pulse-dot 1.2s ease-in-out infinite;
}

.header .status {
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.06em;
	color: var(--muted);
	max-width: 14rem;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.model-bar {
	padding: 0.65rem 1.25rem;
	border-bottom: 1px solid var(--border-strong);
	background: var(--surface);
	font-size: 0.8125rem;
}

.model-bar details {
	border: 1px solid var(--border);
	border-radius: var(--radius-card);
	padding: 0.45rem 0.65rem;
	background: var(--canvas);
	transition: border-color var(--duration-fast);
}

.model-bar details[open] {
	border-color: rgba(255, 255, 255, 0.2);
}

.model-bar details + details,
.model-bar .model-row + details {
	margin-top: 0.5rem;
}

.model-row {
	display: flex;
	align-items: center;
	gap: 0.75rem;
}

.model-bar summary,
.role-models-details summary,
.endpoint-details summary {
	cursor: pointer;
	color: var(--muted);
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.1em;
