	min-width: 0;
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.model-label select,
.role-model-label select {
	flex: 1;
	min-width: 0;
	padding: 0.45rem 0.65rem;
	font-size: 0.8125rem;
	cursor: pointer;
}

.endpoint-form {
	display: flex;
	flex-wrap: wrap;
	gap: 0.5rem 0.75rem;
	align-items: flex-end;
	margin-top: 0.5rem;
}

.endpoint-form label {
	display: flex;
	flex-direction: column;
	gap: 0.25rem;
	color: var(--muted);
	font-family: var(--mono);
	font-size: 0.65rem;
	letter-spacing: 0.1em;
