	margin-bottom: 0.4rem;
}

/* Status bars */

.activity-bar {
	padding: 0.5rem 1.25rem;
	background: rgba(255, 255, 255, 0.03);
	border-bottom: 1px solid var(--border-strong);
	font-family: var(--mono);
	font-size: 0.75rem;
