	padding: 1.25rem;
	animation: fade-in var(--duration-fast) ease both;
}

.modal {
	background: var(--surface-raised);
	border: 1px solid var(--border-strong);
	border-radius: var(--radius-card);
	padding: 1.5rem;
	min-width: 320px;
	max-width: 90vw;
