		padding: 0.85rem 1rem 1rem;
	}

	.messages {
		padding: 1rem;
	}
}

import type {
	HubClientMessage,
	HubCommandResultMessage,
	HubModelInfo,
	HubModelsConfigPayload,
	HubRoleContentPayload,
	HubRoleSummaryPayload,
	HubRoomConfigPayload,
	HubRoomSummary,
	HubServerMessage,
} from "./protocol.ts";

export type MessageHandler = (msg: HubServerMessage) => void;

function uuidV4(): string {
	const c = globalThis.crypto as Crypto | undefined;
	if (c && typeof c.randomUUID === "function") return c.randomUUID();
	const bytes = new Uint8Array(16);
	if (c && typeof c.getRandomValues === "function") {
		c.getRandomValues(bytes);
	} else {
		for (let i = 0; i < 16; i++) bytes[i] = Math.floor(Math.random() * 256);
	}
	bytes[6] = (bytes[6]! & 0x0f) | 0x40;
	bytes[8] = (bytes[8]! & 0x3f) | 0x80;
	const hex: string[] = [];
	for (let i = 0; i < 16; i++) hex.push(bytes[i]!.toString(16).padStart(2, "0"));
	return `${hex.slice(0, 4).join("")}-${hex.slice(4, 6).join("")}-${hex.slice(6, 8).join("")}-${hex.slice(8, 10).join("")}-${hex.slice(10, 16).join("")}`;
}

type CommandResolver = {
	resolve: (data: unknown) => void;
	reject: (error: Error) => void;
};

export class HubClient {
	private ws: WebSocket | null = null;
	private handlers: MessageHandler[] = [];
	private readonly pendingCommands = new Map<string, CommandResolver>();
	private readonly hubUrl: string;
	private roomId: string;
	private readonly token: string;
	private readonly displayName: string;
	private joined = false;

	constructor(hubUrl: string, roomId: string, token: string, displayName: string) {
		this.hubUrl = hubUrl;
		this.roomId = roomId;
		this.token = token;
		this.displayName = displayName;
	}

	getRoomId(): string {
		return this.roomId;
	}

	isJoined(): boolean {
		return this.joined;
	}

	onMessage(handler: MessageHandler): () => void {
		this.handlers.push(handler);
		return () => {
			this.handlers = this.handlers.filter((h) => h !== handler);
		};
	}

	/** Open WebSocket only (no join). */
	openSocket(): Promise<void> {
		return new Promise((resolve, reject) => {
			let settled = false;
			const fail = (error: Error) => {
				if (settled) return;
				settled = true;
				reject(error);
			};

			const timeoutId = setTimeout(() => {
				fail(new Error("Connection timed out waiting for hub."));
				this.ws?.close();
			}, 30_000);

			this.ws = new WebSocket(this.hubUrl);
			this.ws.onopen = () => {
				if (!settled) {
					settled = true;
					clearTimeout(timeoutId);
					resolve();
				}
			};
			this.ws.onmessage = (ev) => this.dispatchMessage(ev);
			this.ws.onerror = () => fail(new Error(`WebSocket error connecting to ${this.hubUrl}`));
			this.ws.onclose = (ev) => {
				clearTimeout(timeoutId);
				if (!settled) {
					fail(new Error(`WebSocket closed (${ev.code})`));
				}
			};
		});
	}

	connect(): Promise<void> {
		return this.openSocket().then(() => this.join(this.roomId));
	}

	reconnect(roomId: string): Promise<void> {
		return this.switchRoom(roomId);
	}

	leave(): Promise<void> {
		if (!this.joined) {
			return Promise.resolve();
		}
		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error("Leave timed out"));
			}, 30_000);

			const unsub = this.onMessage((msg) => {
				if (msg.type === "left") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = false;
					resolve();
				}
				if (msg.type === "error" && msg.code === "not_joined") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = false;
					resolve();
				}
			});

			this.send({ type: "leave" });
		});
	}

	async switchRoom(roomId: string): Promise<void> {
		if (this.joined) {
			await this.leave();
		}
		if (this.ws?.readyState !== WebSocket.OPEN) {
			await this.openSocket();
		}
		await this.join(roomId);
	}

	join(roomId: string): Promise<void> {
		this.roomId = roomId;
		if (this.joined) {
			return Promise.reject(new Error("Already joined; call leave() first"));
		}
		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error("Join timed out"));
			}, 120_000);

			const unsub = this.onMessage((msg) => {
				if (msg.type === "joined") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = true;
					resolve();
				}
				if (
					msg.type === "error" &&
					(msg.code === "join_failed" || msg.code === "room_not_found" || msg.code === "already_joined")
				) {
					clearTimeout(timeoutId);
					unsub();
					reject(new Error(String(msg.message ?? msg.code)));
				}
			});

			this.send({
				type: "join",
				roomId: this.roomId,
				token: this.token,
				displayName: this.displayName,
			});
		});
	}

	private dispatchMessage(ev: MessageEvent): void {
		try {
			const msg = JSON.parse(String(ev.data)) as HubServerMessage;
			this.handleCommandResult(msg);
			for (const h of this.handlers) {
				h(msg);
			}
		} catch {
			// ignore
		}
	}

	private handleCommandResult(msg: HubServerMessage): void {
		if (msg.type !== "command_result") return;
		const result = msg as HubCommandResultMessage;
		if (!result.id) return;
		const pending = this.pendingCommands.get(result.id);
		if (!pending) return;
		this.pendingCommands.delete(result.id);
		if (result.success) {
			pending.resolve(result.data);
		} else {
			pending.reject(new Error(result.error ?? `${result.command} failed`));
		}
	}

	private sendCommand<T>(message: HubClientMessage, timeoutMs = 30_000): Promise<T> {
		const id = uuidV4();
		return new Promise<T>((resolve, reject) => {
			const timer = setTimeout(() => {
				this.pendingCommands.delete(id);
				reject(new Error(`Command timed out: ${message.type}`));
			}, timeoutMs);

			this.pendingCommands.set(id, {
				resolve: (data) => {
					clearTimeout(timer);
					resolve(data as T);
				},
				reject: (error) => {
					clearTimeout(timer);
					reject(error);
				},
			});

			this.send({ ...message, id });
		});
	}

	send(msg: HubClientMessage): void {
		if (this.ws?.readyState === WebSocket.OPEN) {
			this.ws.send(JSON.stringify(msg));
		}
	}

	async listRooms(): Promise<HubRoomSummary[]> {
		const data = await this.sendCommand<{ rooms: HubRoomSummary[] }>({
			type: "list_rooms",
			token: this.token,
		});
		return data.rooms ?? [];
	}

	async createRoom(roomId: string, title?: string): Promise<void> {
		await this.sendCommand({
			type: "create_room",
			token: this.token,
			roomId,
			title,
		});
	}

	async deleteRoom(roomId: string, deleteFiles = true): Promise<void> {
		await this.sendCommand({
			type: "delete_room",
			token: this.token,
			roomId,
			deleteFiles,
		});
	}

	async getRoomConfig(roomId: string): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "get_room_config",
			token: this.token,
			roomId,
		});
		return data.config ?? {};
	}

	async setRoomConfig(roomId: string, config: HubRoomConfigPayload): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "set_room_config",
			token: this.token,
			roomId,
			config,
		});
		return data.config ?? config;
	}

	async addRoomRole(roleName: string, roomId = this.roomId): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "add_room_role",
			token: this.token,
			roomId,
			roleName,
		});
		return data.config ?? {};
	}

	async removeRoomRole(roleName: string, roomId = this.roomId): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "remove_room_role",
			token: this.token,
			roomId,
			roleName,
		});
		return data.config ?? {};
	}

	async listRoles(): Promise<HubRoleSummaryPayload[]> {
		const data = await this.sendCommand<{ roles: HubRoleSummaryPayload[] }>({
			type: "list_roles",
			token: this.token,
		});
		return data.roles ?? [];
	}

	async getRole(name: string): Promise<HubRoleContentPayload> {
		return this.sendCommand<HubRoleContentPayload>({
			type: "get_role",
			token: this.token,
			name,
		});
	}

	async saveRole(name: string, content: string): Promise<HubRoleContentPayload> {
		return this.sendCommand<HubRoleContentPayload>({
			type: "save_role",
			token: this.token,
			name,
			content,
		});
	}

	async deleteRole(name: string): Promise<void> {
		await this.sendCommand({
			type: "delete_role",
			token: this.token,
			name,
		});
	}

	async getAvailableModels(): Promise<HubModelInfo[]> {
		const data = await this.sendCommand<{ models: HubModelInfo[] }>({ type: "get_available_models" });
		return data.models ?? [];
	}

	async getModelsConfig(): Promise<HubModelsConfigPayload> {
		return this.sendCommand<HubModelsConfigPayload>({ type: "get_models_config" });
	}

	async setRoleModel(
		roleName: string,
		provider: string | null,
		modelId: string | null,
	): Promise<HubModelsConfigPayload> {
		if (provider === null || modelId === null) {
			return this.sendCommand<HubModelsConfigPayload>({ type: "set_role_model", roleName });
		}
		return this.sendCommand<HubModelsConfigPayload>({
			type: "set_role_model",
			roleName,
			provider,
			modelId,
		});
	}

	async setModel(provider: string, modelId: string): Promise<void> {
		await this.sendCommand({ type: "set_model", provider, modelId });
	}

	async setProviderBaseUrl(provider: string, baseUrl: string): Promise<HubModelInfo[]> {
		const data = await this.sendCommand<{ models: HubModelInfo[] }>({
			type: "set_provider_base_url",
			provider,
			baseUrl,
		});
		return data.models ?? [];
	}

	prompt(message: string): void {
		this.send({ type: "prompt", message });
	}

	extensionUiResponse(response: HubClientMessage): void {
		this.send(response);
	}

	disconnect(): void {
		this.joined = false;
		this.ws?.close();
		this.ws = null;
	}
}

export function defaultWsUrl(): string {
	const proto = location.protocol === "https:" ? "wss:" : "ws:";
	return `${proto}//${location.host}/ws`;
}

/** Client-side mirror of hub protocol (subset). */

export interface HubModelInfo {
	provider: string;
	id: string;
	name: string;
	baseUrl: string;
	api: string;
	hasAuth: boolean;
}

export interface HubSessionState {
	model?: { provider?: string; id?: string; name?: string; baseUrl?: string };
	thinkingLevel?: string;
	isStreaming?: boolean;
	[key: string]: unknown;
}

export type HubActivityPhase = "idle" | "replying" | "thinking" | "tool" | "compacting";

export interface HubActivityUpdateMessage extends HubServerMessage {
	type: "activity_update";
	hostDisplayName: string | null;
	phase: HubActivityPhase;
	detail?: string;
}

export type HubServerMessage = { type: string; [key: string]: unknown };
export type HubClientMessage = { type: string; [key: string]: unknown };

export interface HubCommandResultMessage extends HubServerMessage {
	type: "command_result";
	command: string;
	id?: string;
	success: boolean;
	error?: string;
	data?: unknown;
}

export interface HubTaskPlanTask {
	role: string;
	task: string;
	dependsOn?: string[];
}

export interface HubTaskPlanGap {
	description: string;
	reason: string;
}

export interface HubTaskPlan {
	summary: string;
	tasks: HubTaskPlanTask[];
	uncovered: HubTaskPlanGap[];
}

export interface HubRolePlanMessage extends HubServerMessage {
	type: "role_plan";
	plan: HubTaskPlan;
}

export type HubRoleProgressPhase = "started" | "done" | "failed";

export interface HubRoleProgressMessage extends HubServerMessage {
	type: "role_progress";
	role: string;
	taskId: string;
	phase: HubRoleProgressPhase;
	preview?: string;
	fullOutput?: string;
}

export interface HubRoleGapMessage extends HubServerMessage {
	type: "role_gap";
	uncovered: HubTaskPlanGap[];
}

export interface HubRoleModelEntry {
	name: string;
	description: string;
	modelRef?: string;
	fileModelRef?: string;
}

export interface HubModelsConfigPayload {
	models: HubModelInfo[];
	catalog: string[];
	sessionModelRef?: string;
	roles: HubRoleModelEntry[];
}

export interface HubRoomSummary {
	roomId: string;
	title?: string;
	createdAt: string;
	updatedAt: string;
	clientCount?: number;
}

export interface HubRoomRoleOverridePayload {
	skills?: string[];
	rules?: string;
	tools?: string[];
	model?: string;
}

export interface HubRoomConfigPayload {
	roleNames?: string[];
	skills?: string[];
	rules?: string;
	roleOverrides?: Record<string, HubRoomRoleOverridePayload>;
	rolesEnabled?: boolean;
}

export interface HubRoleSummaryPayload {
	name: string;
	description: string;
	source: "user" | "project";
	filePath: string;
	model?: string;
	tools?: string[];
	skills?: string[];
	rulesPath?: string;
	systemPromptPreview: string;
}

export interface HubRoleContentPayload {
	name: string;
	source: "user" | "project";
	filePath: string;
	content: string;
}

{
	"name": "@earendil-works/pi-web",
	"version": "0.75.3",
	"description": "Web client for pi LAN hub",
	"private": true,
	"type": "module",
	"scripts": {
		"clean": "shx rm -rf dist",
		"build": "node scripts/build.mjs",
		"dev": "node scripts/build.mjs --watch"
	},
	"devDependencies": {
		"esbuild": "0.28.0",
		"shx": "0.4.0",
		"typescript": "5.9.3"
	},
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/earendil-works/pi-mono.git",
		"directory": "packages/web"
	}
}

import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

function loadEsbuild() {
	const require = createRequire(import.meta.url);
	for (const p of ["esbuild", "../../../node_modules/esbuild"]) {
		try {
			return require(p);
		} catch {
			// try next
		}
	}
	throw new Error("esbuild not found; run npm install from repo root");
}

const { build } = loadEsbuild();

const __dirname = dirname(fileURLToPath(import.meta.url));
const pkgRoot = join(__dirname, "..");
const outDir = join(pkgRoot, "dist");

mkdirSync(outDir, { recursive: true });

await build({
	entryPoints: [join(pkgRoot, "src", "main.ts")],
	bundle: true,
	format: "esm",
	platform: "browser",
	outdir: outDir,
	sourcemap: true,
});

const html = readFileSync(join(pkgRoot, "index.html"), "utf8")
	.replace('/src/style.css', './style.css')
	.replace('/src/main.ts', './main.js');
writeFileSync(join(outDir, "index.html"), html);
copyFileSync(join(pkgRoot, "src", "style.css"), join(outDir, "style.css"));

console.log("Built pi-web to", outDir);

