:root {
  /* Canvas & surfaces */
  --canvas: #050508;
  --surface: #0c0c12;
  --surface-raised: #12121a;
  --surface-hover: rgba(255, 255, 255, 0.03);

  /* Borders */
  --border: rgba(255, 255, 255, 0.06);
  --border-strong: rgba(255, 255, 255, 0.10);

  /* Text */
  --text: #f0f0f2;
  --text-body: #a0a0b0;
  --muted: #68687a;

  /* Accent — cool white with a whisper of violet */
  --accent: #e8e8f0;
  --accent-hover: #ffffff;
  --accent-ink: #0c0c12;
  --accent-glow: rgba(200, 200, 255, 0.08);

  /* Semantic */
  --user-bg: rgba(200, 200, 255, 0.04);
  --user-border: rgba(200, 200, 255, 0.10);
  --assistant-bg: #12121a;
  --tool-bg: #0c0c12;
  --error: #f87171;
  --error-bg: rgba(248, 113, 113, 0.08);
  --error-border: rgba(248, 113, 113, 0.18);
  --warning-bg: rgba(251, 191, 36, 0.08);
  --warning-text: #fbbf24;
  --plan-bg: rgba(255, 255, 255, 0.03);
  --progress: #c8c8d0;
  --success: #6ee7b7;
  --success-bg: rgba(110, 231, 183, 0.08);

  /* Typography */
  --font-display: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: "JetBrains Mono", "IBM Plex Mono", ui-monospace, "SF Mono", monospace;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-pill: 9999px;

  /* Motion */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-normal: 280ms;
  --duration-slow: 420ms;

  /* Layout */
  --sidebar-width: 300px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
  color-scheme: dark;
}

body {
  margin: 0;
  font-family: var(--font);
  font-weight: 400;
  letter-spacing: -0.02em;
  background: var(--canvas);
  color: var(--text-body);
  height: 100vh;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* === Ambient Background === */

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(ellipse 75% 50% at 50% -20%, rgba(140, 140, 220, 0.06), transparent 55%),
    radial-gradient(ellipse 50% 35% at 90% 90%, rgba(200, 180, 255, 0.04), transparent 50%),
    radial-gradient(ellipse 40% 30% at 10% 80%, rgba(120, 160, 255, 0.03), transparent 45%);
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(circle at 70% 20%, rgba(255, 255, 255, 0.015) 0%, transparent 40%),
    radial-gradient(circle at 30% 70%, rgba(200, 200, 255, 0.01) 0%, transparent 35%);
}

/* === App Shell === */

#app {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  height: 100vh;
  transition: opacity var(--duration-fast) ease;
}

#app.view-exit {
  opacity: 0;
}

#app.view-enter {
  animation: view-crossfade var(--duration-normal) var(--ease-out) both;
}

/* === Focus === */

:focus-visible {
  outline: 2px solid rgba(200, 200, 255, 0.5);
  outline-offset: 2px;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible,
button:focus-visible {
  outline: 2px solid rgba(200, 200, 255, 0.4);
  outline-offset: 2px;
}

/* === Scrollbar === */

::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.10);
  border-radius: 2px;
  transition: background var(--duration-fast);
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.18);
}

/* === Shared Controls === */

.secondary-btn {
  padding: 0.45rem 0.9rem;
  background: transparent;
  color: var(--text-body);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-pill);
  cursor: pointer;
  font: inherit;
  font-size: 0.8125rem;
  letter-spacing: -0.01em;
  transition:
    border-color var(--duration-fast),
    color var(--duration-fast),
    background var(--duration-fast),
    transform var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast);
  user-select: none;
  white-space: nowrap;
}

.secondary-btn:hover {
  border-color: rgba(255, 255, 255, 0.20);
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 0 1px 6px rgba(255, 255, 255, 0.04);
}

.secondary-btn:active {
  transform: scale(0.97);
}

input,
textarea,
select {
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font: inherit;
  letter-spacing: -0.01em;
  transition:
    border-color var(--duration-fast),
    box-shadow var(--duration-fast);
}

input:hover,
textarea:hover,
select:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: rgba(200, 200, 255, 0.28);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

input::placeholder,
textarea::placeholder {
  color: var(--muted);
}

/* === Connect (Sign-in) Screen === */

.connect-shell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 2.5rem 1.25rem;
}

.connect-hero {
  text-align: center;
  margin-bottom: 2.5rem;
  animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.connect-hero .eyebrow {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 1rem;
}

.connect-hero .logo-symbol {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(200, 200, 255, 0.08), rgba(255, 255, 255, 0.03));
  border: 1px solid var(--border-strong);
  margin-bottom: 1.25rem;
  font-family: var(--mono);
  font-size: 1.6rem;
  font-weight: 400;
  color: var(--text);
  letter-spacing: -0.04em;
}

.connect-hero h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 8vw, 4rem);
  font-weight: 250;
  letter-spacing: -0.04em;
  color: var(--text);
  line-height: 1.05;
}

.connect-panel {
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1.75rem;
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  animation: fade-up var(--duration-normal) var(--ease-out) 0.08s both;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.3);
}

.connect-panel .hint {
  margin: 0 0 0.25rem;
  font-size: 0.8125rem;
  line-height: 1.6;
  color: var(--muted);
  letter-spacing: -0.01em;
}

.connect-panel label {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.connect-panel label:nth-of-type(1) { animation-delay: 0.12s; }
.connect-panel label:nth-of-type(2) { animation-delay: 0.16s; }
.connect-panel label:nth-of-type(3) { animation-delay: 0.20s; }

.connect-panel label span {
