/* === Room Lobby === */

.lobby-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 560px;
  margin: 0 auto;
  padding: 1.25rem 1.25rem 2rem;
  animation: fade-in var(--duration-normal) var(--ease-out) both;
}

.lobby-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0 1.25rem;
  border-bottom: 1px solid var(--border-strong);
