}

.lobby-title {
  margin: 0;
  flex: 1;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 300;
  letter-spacing: -0.03em;
  color: var(--text);
}

.lobby-user {
  font-family: var(--mono);
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.lobby-create-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.lobby-create-row input {
  flex: 1;
  padding: 0.65rem 0.85rem;
}

.room-list {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.room-list-empty {
  padding: 2rem 0.5rem;
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

.room-list li {
  display: flex;
  align-items: stretch;
  gap: 0.35rem;
  animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.room-row {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.3rem;
  text-align: left;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-raised);
  padding: 0.9rem 1.1rem;
  cursor: pointer;
  font: inherit;
  color: var(--text);
  transition:
    border-color var(--duration-fast),
    background var(--duration-fast),
    transform var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast);
}

.room-row:hover {
  border-color: rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.03);
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
}

.room-row:active {
  transform: translateY(0);
}

.room-row.active {
  border-left: 2px solid var(--accent);
  background: rgba(200, 200, 255, 0.04);
}

.room-row-title {
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: -0.02em;
}

.room-card-meta {
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.06em;
  color: var(--muted);
}

.room-row-actions {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.room-row-actions .secondary-btn {
  font-size: 0.75rem;
  padding: 0.4rem 0.65rem;
}

.header-rooms-btn {
  margin-right: 0.25rem;
  font-size: 0.75rem;
  padding: 0.4rem 0.75rem;
}

/* === Chat Layout === */

.chat-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  height: 100%;
  position: relative;
}

.sidebar-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 40;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  transition: opacity var(--duration-fast) ease;
  pointer-events: none;
}

.sidebar-backdrop.visible {
  opacity: 1;
  pointer-events: auto;
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-strong);
  background: var(--surface);
  overflow-y: auto;
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: transform var(--duration-normal) var(--ease-out);
}

.sidebar-section {
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.4rem 0.5rem;
  background: transparent;
  border-bottom: 1px solid var(--border);
  animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.sidebar-section:nth-child(1) { animation-delay: 0.04s; }
.sidebar-section:nth-child(2) { animation-delay: 0.08s; }
.sidebar-section:nth-child(3) { animation-delay: 0.12s; }
.sidebar-section:nth-child(4) { animation-delay: 0.16s; }

.sidebar-section summary {
  cursor: pointer;
  font-weight: 500;
  color: var(--text);
  padding: 0.5rem 0.35rem;
  border-radius: var(--radius-sm);
  transition: background var(--duration-fast);
  font-size: 0.85rem;
}

.sidebar-section summary:hover {
  background: rgba(255, 255, 255, 0.04);
}

.sidebar-section input,
.sidebar-section textarea,
.sidebar-section select {
  width: 100%;
  margin: 0.35rem 0;
  padding: 0.5rem 0.6rem;
  font-size: 0.8125rem;
  border-radius: var(--radius-sm);
}

.sidebar-section label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  color: var(--text-body);
  margin: 0.35rem 0;
}

.sidebar-row,
.room-actions,
.connect-rooms .room-actions {
  display: flex;
  gap: 0.35rem;
  flex-wrap: wrap;
  margin-top: 0.35rem;
}

.rooms-list {
  list-style: none;
  margin: 0.5rem 0;
  padding: 0;
}

.rooms-list li {
  margin: 0.15rem 0;
}

.room-link {
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  padding: 0.45rem 0.55rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font: inherit;
  color: var(--text-body);
  border-left: 2px solid transparent;
  transition:
    background var(--duration-fast),
    color var(--duration-fast),
    border-color var(--duration-fast);
}

.room-link:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}

.room-link.active {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text);
  border-left-color: var(--accent);
}

.role-editor {
  width: 100%;
  font-family: var(--mono);
  font-size: 0.75rem;
  margin: 0.35rem 0;
  min-height: 8rem;
  padding: 0.6rem 0.7rem;
  line-height: 1.5;
  border-radius: var(--radius-sm);
}

.role-meta {
  font-size: 0.65rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
  word-break: break-all;
  font-family: var(--mono);
}

.danger-btn {
  color: var(--error);
}

.danger-btn:hover {
  border-color: rgba(248, 113, 113, 0.30);
  color: var(--error);
  background: rgba(248, 113, 113, 0.06);
}

.room-assigned-list {
  list-style: none;
  margin: 0.5rem 0;
  padding: 0;
}

.room-assigned-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  margin: 0.25rem 0;
  padding: 0.25rem 0;
}

.room-assigned-item span {
  font-size: 0.85rem;
  color: var(--text);
}

/* === Chat Panel === */

.chat-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  animation: fade-in var(--duration-normal) var(--ease-out) both;
}

/* === Header === */

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1.25rem;
  border-bottom: 1px solid var(--border-strong);
  background: rgba(5, 5, 8, 0.78);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.sidebar-toggle {
  display: none;
  flex-shrink: 0;
  padding: 0.4rem 0.65rem;
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-pill);
  cursor: pointer;
  font: inherit;
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  transition:
    border-color var(--duration-fast),
    background var(--duration-fast);
}

.sidebar-toggle:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.18);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-width: 0;
}

.header-brand .logo {
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: -0.03em;
  color: var(--text);
  white-space: nowrap;
}

.header-brand .room {
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
}

.header .status-wrap {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  flex-shrink: 0;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--muted);
  flex-shrink: 0;
  transition: background var(--duration-normal), box-shadow var(--duration-normal);
}

.status-dot.live {
  background: var(--success);
  box-shadow: 0 0 12px rgba(110, 231, 183, 0.30);
  animation: pulse-dot 2s ease-in-out infinite;
}

.status-dot.connecting {
  background: #525268;
  animation: pulse-dot 1.2s ease-in-out infinite;
}

.header .status {
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.06em;
  color: var(--muted);
  max-width: 14rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* === Model Bar === */

.model-bar {
  padding: 0.65rem 1.25rem;
  border-bottom: 1px solid var(--border-strong);
  background: var(--surface);
  font-size: 0.8125rem;
}

.model-bar details {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.45rem 0.7rem;
  background: var(--canvas);
  transition: border-color var(--duration-fast);
}

.model-bar details[open] {
  border-color: rgba(200, 200, 255, 0.12);
}

.model-bar details + details,
.model-bar .model-row + details {
  margin-top: 0.5rem;
}

.model-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.model-bar summary,
.role-models-details summary,
.endpoint-details summary {
  cursor: pointer;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  user-select: none;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.model-bar summary::-webkit-details-marker,
.role-models-details summary::-webkit-details-marker,
.endpoint-details summary::-webkit-details-marker {
  display: none;
}

.model-bar summary::after,
.role-models-details summary::after,
.endpoint-details summary::after {
  content: "+";
  font-size: 0.8rem;
  opacity: 0.4;
  margin-left: auto;
  transition: transform var(--duration-fast);
}

.model-bar details[open] summary::after,
.role-models-details[open] summary::after,
.endpoint-details[open] summary::after {
  transform: rotate(45deg);
}

.role-models-form {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.5rem;
}

.role-model-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.role-model-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 6rem;
  color: var(--text-body);
  font-size: 0.8125rem;
}

.role-model-label select {
  flex: 1;
  min-width: 12rem;
}

.model-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--muted);
  flex: 1;
  min-width: 0;
  font-family: var(--mono);
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.model-label select,
.role-model-label select {
  flex: 1;
  min-width: 0;
  padding: 0.5rem 0.7rem;
  font-size: 0.8125rem;
  cursor: pointer;
}

.endpoint-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.75rem;
  align-items: flex-end;
  margin-top: 0.5rem;
}

.endpoint-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  flex: 1;
  min-width: 140px;
}

.endpoint-form label input {
  padding: 0.5rem 0.7rem;
  font-size: 0.8125rem;
}

/* === Messages === */

.messages {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  scroll-behavior: smooth;
}

.msg {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 0.85rem 1rem;
  border-radius: var(--radius-lg);
  max-width: min(88%, 44rem);
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.9rem;
  line-height: 1.6;
  letter-spacing: -0.01em;
  position: relative;
}

.msg.msg-animate-in {
  animation: msg-in var(--duration-normal) var(--ease-out) forwards;
}

.msg.user {
  align-self: flex-end;
  background: var(--user-bg);
  border: 1px solid var(--user-border);
  color: var(--text);
  border-bottom-right-radius: var(--radius-sm);
}

.msg.assistant {
  align-self: flex-start;
  background: var(--assistant-bg);
  border: 1px solid var(--border-strong);
  color: var(--text-body);
  border-bottom-left-radius: var(--radius-sm);
}

.msg.assistant::before {
  content: "";
  position: absolute;
  top: -1px;
  left: -1px;
  right: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(200, 200, 255, 0.12), transparent);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  pointer-events: none;
}

.msg.tool {
  align-self: flex-start;
  background: var(--tool-bg);
  border: 1px solid var(--border);
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.02em;
  color: var(--muted);
  padding: 0.7rem 0.9rem;
  border-radius: var(--radius-md);
}

.msg.role-plan,
.msg.role-output,
.msg.role {
  align-self: flex-start;
  background: var(--plan-bg);
  border: 1px solid var(--border);
  border-left: 2px solid rgba(200, 200, 255, 0.15);
  font-size: 0.85rem;
  white-space: pre-wrap;
  border-radius: var(--radius-md);
}

.msg.role-output {
  border-left-color: rgba(200, 200, 255, 0.30);
}

.msg .meta {
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.msg .msg-body {
  line-height: 1.55;
}

.msg .msg-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  font-size: 0.55rem;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: uppercase;
  flex-shrink: 0;
  margin-right: 0.4rem;
}

.msg.user .msg-avatar {
  background: rgba(200, 200, 255, 0.12);
  color: var(--text);
}

.msg.assistant .msg-avatar {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-body);
}

/* === Status Bars === */

.activity-bar {
  padding: 0.5rem 1.25rem;
  background: rgba(200, 200, 255, 0.03);
  border-bottom: 1px solid var(--border-strong);
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  color: var(--progress);
  animation: slide-down var(--duration-normal) var(--ease-out) both;
}

.activity-bar.hidden {
  display: none;
}

.role-gap-bar {
  padding: 0.55rem 1.25rem;
  background: var(--warning-bg);
  border-bottom: 1px solid rgba(251, 191, 36, 0.15);
  font-size: 0.8125rem;
  color: var(--warning-text);
  animation: slide-down var(--duration-normal) var(--ease-out) both;
}

.role-plan-panel {
  padding: 0.65rem 1.25rem;
  background: var(--plan-bg);
  border-bottom: 1px solid var(--border-strong);
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.02em;
  color: var(--muted);
  white-space: pre-wrap;
  max-height: 8rem;
  overflow-y: auto;
  animation: slide-down var(--duration-normal) var(--ease-out) both;
}

.role-progress-bar {
  padding: 0.45rem 1.25rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border-strong);
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  color: var(--progress);
  animation: slide-down var(--duration-fast) var(--ease-out) both;
}

.queue-bar {
  padding: 0.45rem 1.25rem;
  background: var(--surface);
  border-top: 1px solid var(--border-strong);
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

/* === Composer === */

.composer {
  display: flex;
  gap: 0.65rem;
  align-items: flex-end;
  padding: 0.9rem 1.25rem 1.1rem;
  border-top: 1px solid var(--border-strong);
  background: rgba(5, 5, 8, 0.82);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.composer textarea {
  flex: 1;
  min-height: 2.75rem;
  max-height: 8rem;
  resize: none;
  padding: 0.75rem 1.1rem;
  border-radius: var(--radius-pill);
  font-size: 0.9rem;
  line-height: 1.45;
}

.composer .btn-send {
  flex-shrink: 0;
  padding: 0.7rem 1.2rem;
  background: var(--accent);
  color: var(--accent-ink);
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  font-size: 0.875rem;
  letter-spacing: -0.02em;
  transition:
    transform var(--duration-fast) var(--ease-out),
    background var(--duration-fast),
    box-shadow var(--duration-fast),
    opacity var(--duration-fast);
  user-select: none;
}

.composer .btn-send:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(200, 200, 255, 0.15);
}

.composer .btn-send:active {
  transform: translateY(0);
}

.composer .btn-send:disabled {
  opacity: 0.4;
  cursor: default;
  transform: none;
}

/* === Modal === */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 1.25rem;
  animation: fade-in var(--duration-fast) ease both;
}

.modal {
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  min-width: 320px;
  max-width: 90vw;
  animation: scale-in var(--duration-normal) var(--ease-out) both;
  box-shadow: 0 16px 64px rgba(0, 0, 0, 0.4);
}

.modal h3 {
  margin: 0 0 0.75rem;
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 300;
  letter-spacing: -0.03em;
  color: var(--text);
}

.modal p {
  margin: 0 0 0.75rem;
  color: var(--text-body);
  font-size: 0.9rem;
  line-height: 1.55;
}

.modal .options {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.modal button.option {
  text-align: left;
  padding: 0.65rem 0.9rem;
  background: var(--canvas);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-body);
  cursor: pointer;
  font: inherit;
  letter-spacing: -0.01em;
  transition:
    border-color var(--duration-fast),
    color var(--duration-fast),
    background var(--duration-fast);
}

.modal button.option:hover {
  border-color: rgba(200, 200, 255, 0.20);
  color: var(--text);
  background: rgba(200, 200, 255, 0.04);
}

.modal input[type="text"],
.modal textarea {
  width: 100%;
  padding: 0.7rem 0.9rem;
}

.modal .actions {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
}

.modal .actions button {
  padding: 0.6rem 1.1rem;
  border-radius: var(--radius-pill);
  cursor: pointer;
  font: inherit;
  font-size: 0.875rem;
  letter-spacing: -0.02em;
  transition:
    opacity var(--duration-fast),
    background var(--duration-fast),
    border-color var(--duration-fast);
}

.modal .actions button:first-child {
  background: var(--accent);
  color: var(--accent-ink);
  border: none;
}

.modal .actions button:first-child:hover {
  background: var(--accent-hover);
}

.modal .actions button:last-child {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--border-strong);
}

.modal .actions button:hover {
  opacity: 0.9;
}

.modal .actions button:last-child:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.18);
}

/* === Error Banner === */

.error-banner {
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: var(--radius-md);
  color: var(--error);
  padding: 0.6rem 0.85rem;
  font-size: 0.8125rem;
  letter-spacing: -0.01em;
  animation: slide-down var(--duration-fast) var(--ease-out) both;
}

.hidden {
  display: none !important;
}

/* === Keyframes === */

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes view-crossfade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes msg-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes slide-down {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* === Reduced Motion === */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  #app.view-exit,
  #app.view-enter {
    transition: none;
    animation: none;
  }

  .messages {
    scroll-behavior: auto;
  }
}

/* === Mobile === */

@media (max-width: 640px) {
  .sidebar-backdrop {
    display: block;
  }

  .sidebar-toggle {
    display: inline-block;
  }

  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    z-index: 50;
    height: 100vh;
    transform: translateX(-100%);
    box-shadow: 8px 0 40px rgba(0, 0, 0, 0.5);
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .chat-layout {
    flex-direction: column;
  }

  .header {
    flex-wrap: wrap;
    padding: 0.65rem 1rem;
  }

  .header .status {
    max-width: 100%;
  }

  .composer {
    padding: 0.75rem 1rem 0.9rem;
  }

  .messages {
    padding: 1rem;
  }

  .msg {
    max-width: 96%;
  }

  .connect-hero .logo-symbol {
    width: 44px;
    height: 44px;
    font-size: 1.3rem;
  }
}

